/**
 * @distilled.cloud/anthropic — Anthropic API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from Anthropic's
 * OpenAPI spec). Everything else in this folder is hand-written.
 *
 * Operations are exported from the package root. Beta routes that shadow a
 * GA operation carry `Beta` in the noun (`createBetaMessage` next to
 * `createMessage`); beta-only APIs (managed agents, the Admin API) do not.
 * Dual-mode endpoints have an event-stream sibling: `createMessageStream`
 * returns a `Stream` of message events.
 *
 * @example
 * ```ts
 * import * as Anthropic from "@distilled.cloud/anthropic";
 *
 * const message = yield* Anthropic.createMessage({
 *   model: "claude-haiku-4-5-20251001",
 *   max_tokens: 64,
 *   messages: [{ role: "user", content: "Hello, Claude" }],
 * });
 * ```
 */
export * from "./credentials.ts";
export type { Config as AnthropicClientConfig } from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { AnthropicProtocol, type AnthropicOpError, type AnthropicOpContext } from "./protocol.ts";
export { paginateWithDefaults } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
export * from "./services/anthropic.ts";
